    AggregateLoadError,
    ExtraFieldsLoadError,
    NoRequiredFieldsLoadError,
    TypeLoadError,
)
from tests_helpers import raises_exc, with_trail


@dataclass
class TwoFields:
    a: int = 0
    b: int = 0


@dataclass
class ReqFields:
    a: int
    b: int


@dataclass
class Snake:
    a_b: int = 0
    c: int = 0


@dataclass
class WithExtras:
    extra: Dict[str, int] = field(default_factory=dict)
    a: int = 0


@dataclass
class Inner:
    x: int


@dataclass
class Outer:
    inner: Inner
    y: int = 1


def _retort(*recipe, debug_trail=DebugTrail.FIRST) -> Retort:
    return Retort(recipe=list(recipe), debug_trail=debug_trail)


# --------------------------------------------------------------------------- #
#  Loading: primary key and alias fallback
# --------------------------------------------------------------------------- #


def test_load_via_primary_key():
    loader = _retort(name_mapping(aliases={"a": ["x", "y"]})).get_loader(TwoFields)
    assert loader({"a": 1, "b": 2}) == TwoFields(1, 2)


def test_load_via_single_alias():
    loader = _retort(name_mapping(aliases={"a": "x"})).get_loader(TwoFields)
    assert loader({"x": 1, "b": 2}) == TwoFields(1, 2)


def test_load_via_alias_fallback():
    loader = _retort(name_mapping(aliases={"a": ["x", "y"]})).get_loader(TwoFields)
    assert loader({"x": 1, "b": 2}) == TwoFields(1, 2)
    assert loader({"y": 1, "b": 2}) == TwoFields(1, 2)


def test_alias_absent_uses_default():
    loader = _retort(name_mapping(aliases={"a": ["x", "y"]})).get_loader(TwoFields)
    assert loader({"b": 2}) == TwoFields(0, 2)


def test_dumper_unaffected_by_aliases():
    retort = _retort(name_mapping(aliases={"a": ["x", "y"]}))
    assert retort.dump(TwoFields(1, 2)) == {"a": 1, "b": 2}


def test_map_and_aliases_coexist():
    retort = _retort(name_mapping(map={"a": "primary"}, aliases={"a": "alt"}))
    assert retort.get_loader(TwoFields)({"primary": 1, "b": 2}) == TwoFields(1, 2)
    assert retort.get_loader(TwoFields)({"alt": 5, "b": 2}) == TwoFields(5, 2)
    assert retort.dump(TwoFields(1, 2)) == {"primary": 1, "b": 2}


def test_aliases_merge_from_multiple_recipes():
    loader = _retort(
        name_mapping(aliases={"a": "x"}),
        name_mapping(aliases={"a": "y"}),
    ).get_loader(TwoFields)
    assert loader({"x": 1, "b": 2}) == TwoFields(1, 2)
    assert loader({"y": 1, "b": 2}) == TwoFields(1, 2)


# --------------------------------------------------------------------------- #
#  Multi-key conflict
# --------------------------------------------------------------------------- #


def test_multi_key_conflict_primary_and_alias(debug_trail, trail_select):
    loader = _retort(
        name_mapping(aliases={"a": ["x", "y"]}),
        debug_trail=debug_trail,
    ).get_loader(TwoFields)
    data = {"a": 1, "x": 2, "b": 0}
    error = ExtraFieldsLoadError({"a", "x"}, data)
    raises_exc(
        trail_select(
            disable=error,
            first=with_trail(error, ["a"]),
            all=AggregateLoadError(
                f"while loading model {TwoFields}",
                [with_trail(error, ["a"])],
            ),
        ),
        lambda: loader(data),
    )


def test_multi_key_conflict_two_aliases(debug_trail, trail_select):
    loader = _retort(
        name_mapping(aliases={"a": ["x", "y"]}),
        debug_trail=debug_trail,
    ).get_loader(TwoFields)
    data = {"x": 1, "y": 2, "b": 0}
    error = ExtraFieldsLoadError({"x", "y"}, data)
    raises_exc(
        trail_select(
            disable=error,
            first=with_trail(error, ["a"]),
            all=AggregateLoadError(
                f"while loading model {TwoFields}",
                [with_trail(error, ["a"])],
            ),
        ),
        lambda: loader(data),
    )


# --------------------------------------------------------------------------- #
#  Extra policies
# --------------------------------------------------------------------------- #


def test_extra_skip_ignores_aliases_and_extras():
    loader = _retort(name_mapping(aliases={"a": "x"})).get_loader(TwoFields)
    assert loader({"x": 5, "junk": 1}) == TwoFields(5, 0)


def test_extra_forbid_recognizes_aliases():
    loader = _retort(
        name_mapping(aliases={"a": "x"}, extra_in=ExtraForbid()),
    ).get_loader(TwoFields)
    assert loader({"x": 5, "b": 2}) == TwoFields(5, 2)
    data = {"x": 5, "zzz": 1}
    raises_exc(
        ExtraFieldsLoadError({"zzz"}, data),
        lambda: loader(data),
    )


def test_extra_collect_does_not_collect_aliases():
    loader = _retort(
        name_mapping(aliases={"a": "x"}, extra_in=["extra"]),
    ).get_loader(WithExtras)
    assert loader({"x": 5, "real_extra": 9}) == WithExtras({"real_extra": 9}, 5)
    assert loader({"a": 5, "real_extra": 9}) == WithExtras({"real_extra": 9}, 5)
    assert loader({"x": 5}) == WithExtras({}, 5)


# --------------------------------------------------------------------------- #
#  Required fields
# --------------------------------------------------------------------------- #


def test_missing_required_with_aliases(debug_trail, trail_select):
    loader = _retort(
        name_mapping(aliases={"a": ["x", "y"]}),
        debug_trail=debug_trail,
    ).get_loader(ReqFields)
    data = {"b": 1}
    error = NoRequiredFieldsLoadError({"a"}, data)
    raises_exc(
        trail_select(
            disable=error,
            first=error,
            all=AggregateLoadError(
                f"while loading model {ReqFields}",
                [error],
            ),
        ),
        lambda: loader(data),
    )


def test_missing_all_required_with_aliases(debug_trail, trail_select):
    loader = _retort(
        name_mapping(aliases={"a": ["x", "y"]}),
        debug_trail=debug_trail,
    ).get_loader(ReqFields)
    data = {}
    error = NoRequiredFieldsLoadError({"a", "b"}, data)
    raises_exc(
        trail_select(
            disable=error,
            first=error,
            all=AggregateLoadError(
                f"while loading model {ReqFields}",
                [error],
            ),
        ),
        lambda: loader(data),
    )


def test_required_satisfied_by_alias():
    loader = _retort(name_mapping(aliases={"a": ["x", "y"]})).get_loader(ReqFields)
    assert loader({"y": 5, "b": 6}) == ReqFields(5, 6)


# --------------------------------------------------------------------------- #
#  Trail
# --------------------------------------------------------------------------- #


def test_trail_reflects_resolved_key():
    loader = _retort(name_mapping(aliases={"a": ["x", "y"]})).get_loader(TwoFields)
    for key, expected in (("x", ["x"]), ("y", ["y"]), ("a", ["a"])):
        error = TypeLoadError(int, "bad")
        raises_exc(
            with_trail(error, expected),
            lambda key=key: loader({key: "bad", "b": 1}),
        )


def test_non_mapping_input_raises_type_error(debug_trail, trail_select):
    loader = _retort(
        name_mapping(aliases={"a": "x"}),
        debug_trail=debug_trail,
    ).get_loader(ReqFields)
    error = TypeLoadError(CollectionsMapping, "bad")
    raises_exc(
        trail_select(
            disable=error,
            first=error,
            all=AggregateLoadError(
                f"while loading model {ReqFields}",
                [error],
            ),
        ),
        lambda: loader("bad"),
    )


def test_nested_alias_trail(debug_trail, trail_select):
    loader = _retort(
        name_mapping(Inner, aliases={"x": "xx"}),
        name_mapping(Outer, aliases={"inner": "inn"}),
        debug_trail=debug_trail,
    ).get_loader(Outer)
    assert loader({"inn": {"xx": 7}, "y": 1}) == Outer(Inner(7), 1)

    bad_error = TypeLoadError(int, "bad")
    raises_exc(
        trail_select(
            disable=bad_error,
            first=with_trail(bad_error, ["inn", "xx"]),
            all=AggregateLoadError(
                f"while loading model {Outer}",
                [with_trail(bad_error, ["inn", "xx"])],
            ),
        ),
        lambda: loader({"inn": {"xx": "bad"}, "y": 1}),
    )

    missing_error = NoRequiredFieldsLoadError({"x"}, {"wrong": 7})
    raises_exc(
        trail_select(
            disable=missing_error,
            first=with_trail(missing_error, ["inn"]),
            all=AggregateLoadError(
                f"while loading model {Outer}",
                [with_trail(missing_error, ["inn"])],
            ),
        ),
        lambda: loader({"inn": {"wrong": 7}, "y": 1}),
    )


# --------------------------------------------------------------------------- #
#  alias_style
# --------------------------------------------------------------------------- #


def test_alias_style_single():
    loader = _retort(name_mapping(alias_style=NameStyle.UPPER_SNAKE)).get_loader(Snake)
    assert loader({"A_B": 1, "C": 2}) == Snake(1, 2)
    assert loader({"a_b": 1, "c": 2}) == Snake(1, 2)
    assert _retort(name_mapping(alias_style=NameStyle.UPPER_SNAKE)).dump(Snake(1, 2)) == {
        "a_b": 1,
        "c": 2,
    }


def test_alias_style_list():
    loader = _retort(
        name_mapping(alias_style=[NameStyle.UPPER_SNAKE, NameStyle.LOWER_KEBAB]),
    ).get_loader(Snake)
    assert loader({"A_B": 1, "C": 2}) == Snake(1, 2)
    assert loader({"a-b": 1, "c": 2}) == Snake(1, 2)
    assert loader({"a_b": 1, "c": 2}) == Snake(1, 2)


def test_alias_style_lower_snake_is_silently_pruned():
    # every generated alias equals the primary key itself, nothing is added
    loader = _retort(name_mapping(alias_style=NameStyle.LOWER_SNAKE)).get_loader(Snake)
    assert loader({"a_b": 1, "c": 2}) == Snake(1, 2)


def test_alias_style_combined_with_explicit_aliases():
    loader = _retort(
        name_mapping(alias_style=NameStyle.UPPER_SNAKE, aliases={"a_b": "custom"}),
    ).get_loader(Snake)
    assert loader({"A_B": 1, "c": 2}) == Snake(1, 2)
    assert loader({"custom": 1, "c": 2}) == Snake(1, 2)
    assert loader({"a_b": 1, "c": 2}) == Snake(1, 2)


def test_explicit_alias_is_literal_and_ignores_name_style():
    retort = _retort(
        name_mapping(name_style=NameStyle.UPPER_SNAKE, aliases={"a": "low_alias"}),
    )
    loader = retort.get_loader(TwoFields)
    assert loader({"A": 1, "B": 2}) == TwoFields(1, 2)
    assert loader({"low_alias": 1, "B": 2}) == TwoFields(1, 2)
    # lowercase primary is not an alias and is dropped by the default skip policy
    assert loader({"a": 1, "B": 2}) == TwoFields(0, 2)
    assert retort.dump(TwoFields(1, 2)) == {"A": 1, "B": 2}


# --------------------------------------------------------------------------- #
#  Creation-time errors
# --------------------------------------------------------------------------- #


def test_explicit_alias_equal_to_own_primary_key_errors():
    with pytest.raises(
        ProviderNotFoundError,
        match="explicit alias equal to its own primary key",
    ):
        _retort(name_mapping(aliases={"a": "a"})).get_loader(TwoFields)


def test_alias_colliding_with_other_field_primary_key_errors():
    with pytest.raises(
        ProviderNotFoundError,
        match="collides with a key of field 'b'",
    ):
        _retort(name_mapping(aliases={"a": "b"})).get_loader(TwoFields)


def test_alias_colliding_with_another_alias_errors():
    with pytest.raises(
        ProviderNotFoundError,
        match="collides with a key of field",
    ):
        _retort(name_mapping(aliases={"a": "z", "b": "z"})).get_loader(TwoFields)


def test_generated_alias_equal_to_own_primary_key_does_not_error():
    # covered by test_alias_style_lower_snake_is_silently_pruned;
    # make sure generation does not fail even when aliased by style only
    _retort(name_mapping(alias_style=NameStyle.LOWER_SNAKE)).get_loader(TwoFields)


def test_invalid_alias_key_errors_at_creation():
    with pytest.raises(ValueError, match="valid field_id"):
        name_mapping(aliases={"a a": "x"})


# --------------------------------------------------------------------------- #
#  as_list
# --------------------------------------------------------------------------- #


def test_as_list_ignores_aliases():
    @dataclass
    class ListModel:
        a: int
        b: int

    loader = _retort(
        name_mapping(aliases={"a": "x"}, as_list=True),
    ).get_loader(ListModel)
    assert loader([1, 2]) == ListModel(1, 2)
    raises_exc(
        TypeLoadError(CollectionsSequence := __import__("collections.abc", fromlist=["Sequence"]).Sequence, {"a": 1, "b": 2}),
        lambda: loader({"a": 1, "b": 2}),
    )


# --------------------------------------------------------------------------- #
#  JSON schema
# --------------------------------------------------------------------------- #


def test_input_schema_exposes_aliases():
    retort = _retort(name_mapping(aliases={"a": ["x", "y"]}))
    schema = generate_json_schema(retort, TwoFields, direction=Direction.INPUT)
    props = schema["$defs"][f"<class {TwoFields}>"]["properties"]
    assert set(props) == {"a", "b", "x", "y"}
    assert props["x"] == props["a"]
    assert props["y"] == props["a"]
    assert schema["$defs"][f"<class {TwoFields}>"]["required"] == ["a"]
    assert schema["$defs"][f"<class {TwoFields}>"]["additional_properties"] is True


def test_input_schema_with_forbid_still_exposes_aliases():
    retort = _retort(
        name_mapping(aliases={"a": ["x", "y"]}, extra_in=ExtraForbid()),
    )
    schema = generate_json_schema(retort, TwoFields, direction=Direction.INPUT)
    inner = schema["$defs"][f"<class {TwoFields}>"]
    assert set(inner["properties"]) == {"a", "b", "x", "y"}
    assert inner["additional_properties"] is False


def test_output_schema_unaffected_by_aliases():
    retort = _retort(name_mapping(aliases={"a": ["x", "y"]}))
    schema = generate_json_schema(retort, TwoFields, direction=Direction.OUTPUT)
    inner = schema["$defs"][f"<class {TwoFields}>"]
    assert set(inner["properties"]) == {"a", "b"}


