# --------------------------------------------------------------------------- #


def test_load_via_primary_key():
    loader = _retort(name_mapping(aliases={"a": ["x", "y"]})).get_loader(TwoFields)
    assert loader({"a": 1, "b": 2}) == TwoFields(1, 2)


def test_load_via_single_alias():
    loader = _retort(name_mapping(aliases={"a": "x"})).get_loader(TwoFields)
    assert loader({"x": 1, "b": 2}) == TwoFields(1, 2)


def test_load_via_alias_fallback():
    loader = _retort(name_mapping(aliases={"a": ["x", "y"]})).get_loader(TwoFields)
    assert loader({"x": 1, "b": 2}) == TwoFields(1, 2)
    assert loader({"y": 1, "b": 2}) == TwoFields(1, 2)


def test_alias_absent_uses_default():
    loader = _retort(name_mapping(aliases={"a": ["x", "y"]})).get_loader(TwoFields)
    assert loader({"b": 2}) == TwoFields(0, 2)


def test_dumper_unaffected_by_aliases():
    retort = _retort(name_mapping(aliases={"a": ["x", "y"]}))
    assert retort.dump(TwoFields(1, 2)) == {"a": 1, "b": 2}


def test_map_and_aliases_coexist():
    retort = _retort(name_mapping(map={"a": "primary"}, aliases={"a": "alt"}))
    assert retort.get_loader(TwoFields)({"primary": 1, "b": 2}) == TwoFields(1, 2)
    assert retort.get_loader(TwoFields)({"alt": 5, "b": 2}) == TwoFields(5, 2)
    assert retort.dump(TwoFields(1, 2)) == {"primary": 1, "b": 2}


def test_aliases_merge_from_multiple_recipes():
    loader = _retort(
        name_mapping(aliases={"a": "x"}),
        name_mapping(aliases={"a": "y"}),
    ).get_loader(TwoFields)
    assert loader({"x": 1, "b": 2}) == TwoFields(1, 2)
    assert loader({"y": 1, "b": 2}) == TwoFields(1, 2)


# --------------------------------------------------------------------------- #
#  Multi-key conflict
# --------------------------------------------------------------------------- #


def test_multi_key_conflict_primary_and_alias(debug_trail, trail_select):
    loader = _retort(
        name_mapping(aliases={"a": ["x", "y"]}),
