def test_nested_alias_trail(debug_trail, trail_select):
    loader = _retort(
        name_mapping(Inner, aliases={"x": "xx"}),
        name_mapping(Outer, aliases={"inner": "inn"}),
        debug_trail=debug_trail,
    ).get_loader(Outer)
    assert loader({"inn": {"xx": 7}, "y": 1}) == Outer(Inner(7), 1)

    raises_exc(
        trail_select(
            disable=TypeLoadError(int, "bad"),
            first=with_trail(TypeLoadError(int, "bad"), ["inn", "xx"]),
            all=AggregateLoadError(
                f"while loading model {Outer}",
                [
                    with_trail(
                        AggregateLoadError(
                            f"while loading model {Inner}",
                            [with_trail(TypeLoadError(int, "bad"), ["xx"])],
                        ),
                        ["inn"],
                    ),
                ],
            ),
        ),
        lambda: loader({"inn": {"xx": "bad"}, "y": 1}),
    )

    raises_exc(
        trail_select(
            disable=NoRequiredFieldsLoadError({"x"}, {"wrong": 7}),
            first=with_trail(NoRequiredFieldsLoadError({"x"}, {"wrong": 7}), ["inn"]),
            all=AggregateLoadError(
                f"while loading model {Outer}",
                [
                    with_trail(
                        AggregateLoadError(
                            f"while loading model {Inner}",
                            [NoRequiredFieldsLoadError({"x"}, {"wrong": 7})],
                        ),
                        ["inn"],
                    ),
                ],
            ),
        ),
        lambda: loader({"inn": {"wrong": 7}, "y": 1}),
    )


