def test_alias_style_single():
    loader = _retort(name_mapping(alias_style=NameStyle.UPPER_SNAKE)).get_loader(Snake)
    assert loader({"A_B": 1, "C": 2}) == Snake(1, 2)
    assert loader({"a_b": 1, "c": 2}) == Snake(1, 2)
    assert _retort(name_mapping(alias_style=NameStyle.UPPER_SNAKE)).dump(Snake(1, 2)) == {
        "a_b": 1,
        "c": 2,
    }


def test_alias_style_list():
    loader = _retort(
        name_mapping(alias_style=[NameStyle.UPPER_SNAKE, NameStyle.LOWER_KEBAB]),
    ).get_loader(Snake)
    assert loader({"A_B": 1, "C": 2}) == Snake(1, 2)
    assert loader({"a-b": 1, "c": 2}) == Snake(1, 2)
    assert loader({"a_b": 1, "c": 2}) == Snake(1, 2)


def test_alias_style_lower_snake_is_silently_pruned():
    # every generated alias equals the primary key itself, nothing is added
    loader = _retort(name_mapping(alias_style=NameStyle.LOWER_SNAKE)).get_loader(Snake)
    assert loader({"a_b": 1, "c": 2}) == Snake(1, 2)


def test_alias_style_combined_with_explicit_aliases():
    loader = _retort(
        name_mapping(alias_style=NameStyle.UPPER_SNAKE, aliases={"a_b": "custom"}),
    ).get_loader(Snake)
    assert loader({"A_B": 1, "c": 2}) == Snake(1, 2)
    assert loader({"custom": 1, "c": 2}) == Snake(1, 2)
    assert loader({"a_b": 1, "c": 2}) == Snake(1, 2)


def test_explicit_alias_is_literal_and_ignores_name_style():
    retort = _retort(
        name_mapping(name_style=NameStyle.UPPER_SNAKE, aliases={"a": "low_alias"}),
    )
    loader = retort.get_loader(TwoFields)
    assert loader({"A": 1, "B": 2}) == TwoFields(1, 2)
    assert loader({"low_alias": 1, "B": 2}) == TwoFields(1, 2)
    # lowercase primary is not an alias and is dropped by the default skip policy
    assert loader({"a": 1, "B": 2}) == TwoFields(0, 2)
    assert retort.dump(TwoFields(1, 2)) == {"A": 1, "B": 2}


