def test_input_schema_exposes_aliases():
    retort = _retort(name_mapping(aliases={"a": ["x", "y"]}))
    schema = generate_json_schema(retort, ReqFields, direction=Direction.INPUT)
    inner = schema["$defs"][str(ReqFields)]
