def stub(*args, **kwargs):
    pass


def make_layouts(*providers):
    input_shape = InputShape(
        fields=tuple(
            InputField(
                id=fld_id,
                type=Any,
                default=NoDefault(),
                metadata={},
                is_required=True,
                original=None,
            )
            for fld_id in ("a", "b")
        ),
        params=tuple(
            Param(field_id=fld_id, name=fld_id, kind=ParamKind.POS_OR_KW)
            for fld_id in ("a", "b")
        ),
        constructor=stub,
        kwargs=ParamKwargs(Any),
        overriden_types=frozenset(("a", "b")),
    )
    output_shape = OutputShape(
        fields=tuple(
            OutputField(
                id=fld_id,
                type=Any,
                default=NoDefault(),
                metadata={},
                accessor=create_attr_accessor(attr_name=fld_id, is_required=True),
                original=None,
            )
            for fld_id in ("a", "b")
        ),
        overriden_types=frozenset(("a", "b")),
    )
    retort = Retort(
        recipe=[
            *providers,
            ValueProvider(InputShapeRequest, input_shape),
            ValueProvider(OutputShapeRequest, output_shape),
        ],
    )
    loc_stack = LocStack(TypeHintLoc(type=TwoFields))
    inp_layout = retort._facade_provide(
        InputNameLayoutRequest(loc_stack=loc_stack, shape=input_shape),
        error_message="cannot provide input name layout",
    )
    out_layout = retort._facade_provide(
        OutputNameLayoutRequest(loc_stack=loc_stack, shape=output_shape),
        error_message="cannot provide output name layout",
    )
    return inp_layout, out_layout


def test_crown_carries_aliases_on_input_only():
    inp_layout, out_layout = make_layouts(
        name_mapping(
            aliases={"a": ["x", "y"]},
            skip=(),
            only=P.ANY,
            map={},
            trim_trailing_underscore=True,
            name_style=None,
            as_list=False,
            omit_default=False,
            extra_in=ExtraSkip(),
            extra_out=ExtraSkip(),
            chain=None,
        ),
    )
    assert inp_layout == InputNameLayout(
        crown=InpDictCrown(
            map={
                "a": InpFieldCrown("a", aliases=("x", "y")),
                "b": InpFieldCrown("b"),
            },
            extra_policy=ExtraSkip(),
        ),
        extra_move=None,
    )
    assert out_layout == OutputNameLayout(
        crown=OutDictCrown(
            map={
                "a": OutFieldCrown("a"),
                "b": OutFieldCrown("b"),
            },
            sieves={},
        ),
        extra_move=None,
    )
